import{_ as n,l as r,o as e,c as i,v as o,p as s,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Ho–Stoll 库存做市","description":"","frontmatter":{"title":"Ho–Stoll 库存做市","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ho-stoll-inventory.md","filePath":"quant/ho-stoll-inventory.md","lastUpdated":1789023840000}'),c={name:"quant/ho-stoll-inventory.md"};function u(m,a,E,A,B,_){const t=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="ho–stoll-库存做市" tabindex="-1">Ho–Stoll 库存做市 <a class="header-anchor" href="#ho–stoll-库存做市" aria-label="Permalink to &quot;Ho–Stoll 库存做市&quot;">​</a></h1><div class="epigraph"><p>即使对手并不比你知情，双向报价仍要补偿你暂时持有的不愿持有的头寸。价差是经销商风险分担的价格，中点随库存偏移。</p><footer>—— Ho and Stoll, Optimal dealer pricing under transactions and return uncertainty, Journal of Financial Economics, 1981</footer></div><p><a href="/quant/easley-ohara-event">上一课</a>在好坏消息之外加入「有无信息事件」，学习对象是体制后验；无交易可以是无事件的证据，价差在事件未决时最宽。从 Kyle 到 Easley–O&#39;Hara，价格移动的原因都是别人可能知情。缺口是对称的另一条范式：对手与你一样无知，你却已经持有一堆股票。Ho–Stoll（1981）在有限地平线上写出经销商的最优买卖报价。本课写这一最优控制，不重写 PIN 似然，也不把 Avellaneda–Stoikov 的强度模型再推一遍。主干里的<a href="/quant/inventory-skew">库存偏度</a>已经把中点随库存平移当作交易台对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信息范式回答「被选中的损失」。库存范式回答：成交会留下头寸，头寸在中间价波动上有风险，风险厌恶的经销商要求即时补偿。若只有处理成本，竞争会把价差压到成本；若还有库存风险，价差必须覆盖持有期间的方差，并且报价要<strong>偏</strong>向把库存送回去的那一侧。问题是：在交易到达不确定、收益不确定的联合下，最优的宽度与偏度如何依赖剩余时间、风险厌恶与存货。</p><p>这与<a href="/quant/kyle-multiperiod">多期 Kyle</a> 的状态完全不同。Kyle 的状态是对 \\(V\\) 的信念；Ho–Stoll 的状态是库存 \\(I\\) 与剩余地平线。把库存引起的中点移动当成「信息揭示」，会把做市商自己的风险转移错读成价格发现。</p><h3 id="竞争做市还是垄断专家" tabindex="-1">竞争做市还是垄断专家 <a class="header-anchor" href="#竞争做市还是垄断专家" aria-label="Permalink to &quot;竞争做市还是垄断专家&quot;">​</a></h3><p>1981 年文章写的是单个经销商的优化。Ho 与 Stoll（1983）把多个经销商的库存放进竞争：谁的库存更极端，谁更急于成交，市场报价由最急的那一侧决定。本课以 1981 年的最优报价为机制，1983 年只作为边界：竞争改变的是谁的库存被看见，不是库存成本这一项消失。</p><p><span class="marginnote">Amihud 与 Mendelson（1980）同样走库存路线，强调合意库存与报价的动态规划。Ho–Stoll 把交易与收益的不确定写进连续时间色彩的优化。资产定价含义留给<a href="/quant/amihud-mendelson">下一课之后的价差溢价</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经销商最大化指数型或均值–方差型终端财富。库存 \\(I\\) 使财富对证券收益 \\(r\\) 暴露 \\(I\\cdot r\\)。交易到达是随机的：更高的买价（对客户）降低被卖给的概率，更低的卖价降低被买走的概率。控制变量是双向报价相对公允中点的宽度与偏度。最优时，宽度随 \\(\\sigma^2\\)、风险厌恶、剩余时间增加；偏度与 \\(I\\) 同号——多头则整体下移报价，鼓励客户买走。</p><p>到达若被写成强度对报价的函数，一阶条件把「成交一笔的价差收入」与「库存方差的边际成本」对齐。这与后来 Avellaneda–Stoikov 的强度做市同族，但 1981 年还没有限价簿排队，对象是专家报价，不是挂在哪一档。</p><h3 id="价差可以对称-中点不必是价值" tabindex="-1">价差可以对称，中点不必是价值 <a class="header-anchor" href="#价差可以对称-中点不必是价值" aria-label="Permalink to &quot;价差可以对称，中点不必是价值&quot;">​</a></h3><p>库存模型允许报价价差对称而中点 \\(\\neq E[V]\\)。中点是库存管理的工具，不是有效价格。经验上若只用中点收益做价格发现，会把库存偏度算进「信息」。Hasbrouck 后来用成交与报价的 VAR 把暂时成分分开，正是因为库存与处理成本都会制造暂时成分。</p>',14)),(e(),s(p,null,{default:l(()=>[h(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E5%BD%93%E5%89%8D%E5%BA%93%E5%AD%98%20I%22%5D%20--%3E%20Skew%5B%22%E6%8A%A5%E4%BB%B7%E5%81%8F%E5%BA%A6%22%5D%0A%20%20Sig%5B%22%E6%94%B6%E7%9B%8A%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20Width%5B%22%E4%BB%B7%E5%B7%AE%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20T%5B%22%E5%89%A9%E4%BD%99%E5%9C%B0%E5%B9%B3%E7%BA%BF%22%5D%20--%3E%20Width%0A%20%20Skew%20--%3E%20Q%5B%22bid%20%2F%20ask%22%5D%0A%20%20Width%20--%3E%20Q%0A%20%20Q%20--%3E%20Fill%5B%22%E9%9A%8F%E6%9C%BA%E6%88%90%E4%BA%A4%22%5D%0A%20%20Fill%20--%3E%20I%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每一笔成交有两本账。现金账：赚到半个价差（或报价改善）。库存账：头寸离合意水平更近或更远，终端方差变。做市商愿意在库存危险时<strong>牺牲价差收入</strong>去换减仓——表现为一侧报价更有攻击性，甚至短时间看起来像「主动吃单」。这不是知情交易，是风险转移。Grossman–Miller 将把这种转移写成跨期风险分担；本课先把它写成单个经销商的一阶条件。</p><p>与信息范式叠加时，同一笔买既可能是知情买，也可能帮你减了空头库存。报价更新必须同时改信念与改 \\(I\\)。O&#39;Hara 强调两条线在数据里纠缠，分解是后文 Stoll / Hasbrouck 的任务。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单一经销商、外生到达、没有知情者，是 1981 年的边界。真实专家同时面对逆向选择，纯库存模型会低估价差、高估「中点偏离即库存」。限价簿上「做市」分散在许多挂单者，没有一个 \\(I\\) 是市场的状态；市场库存是加总，个体可以内部对冲。电子盘的义务做市与撤退，要到高频单元再写。</p><p><span class="marginnote">不要用 Ho–Stoll 去解释公告后价差跳升：那首先是事件不确定与逆向选择。库存解释更适合无公告时段、存货集中、对冲工具暂时失效。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Ho–Stoll（1981）在交易与收益不确定下给出经销商最优双向报价：宽度补偿库存风险，偏度把头寸送回合意水平。</li><li>中点可以离开公允价值而不代表信息；那是库存状态价格。</li><li>1983 年竞争做市让最极端库存的经销商决定市场报价。</li><li>与 Kyle / Easley–O&#39;Hara 的状态变量不同：这里是 \\(I\\)，那里是信念。</li><li>出处：Ho and Stoll, <em>Journal of Financial Economics</em>, 1981；竞争见 Ho and Stoll, <em>Journal of Finance</em>, 1983；合意库存见 Amihud and Mendelson, <em>Journal of Financial Economics</em>, 1980。</li></ul>',8))])}const q=n(c,[["render",u]]);export{f as __pageData,q as default};
